CREATE OR REPLACE FUNCTION public.fn_create_marketplace_order(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_platform_experience_id uuid, p_purchased_by_user_id uuid, p_pricing_model character varying, p_amount_paid numeric, p_currency character varying, p_payment_status character varying, p_transaction_reference character varying, p_purchased_at timestamp with time zone, p_refunded_at timestamp with time zone, p_refund_reason text)  RETURNS SETOF marketplace_orders  LANGUAGE sql AS $function$     INSERT INTO marketplace_orders (         id, tenant_id, organization_id, platform_experience_id, purchased_by_user_id,         pricing_model, amount_paid, currency, payment_status, transaction_reference, purchased_at, refunded_at, refund_reason     ) VALUES (         p_id, p_tenant_id, p_organization_id, p_platform_experience_id, p_purchased_by_user_id,         p_pricing_model, p_amount_paid, p_currency, p_payment_status, p_transaction_reference, p_purchased_at, p_refunded_at, p_refund_reason     )     ON CONFLICT (organization_id, platform_experience_id, transaction_reference) DO UPDATE     SET payment_status = EXCLUDED.payment_status     RETURNING *; $function$ ;
